"""Builds the command reference of the wiki in docs/wiki from the list of commands the test suite keeps.

  wiki.py build   Writes one page per command, one link list per category and dialect, the A-Z index and the list of
                  differences from the originals (Differences) into docs/wiki.
  wiki.py check   Fails if a command has no category, a text file names an unknown command, a link points nowhere,
                  or an example does not compile (pass --blitzcc PATH to compile examples). An example whose first
                  line is ";run" is also run without a window, and what it prints has to match the ```text block
                  that follows it.

What a command is and takes comes from tests/suite/functions.txt. What it does is written by hand in
tools/wiki/text/<Dialect>/<Category>/<CommandName>.md, one file per command, so that changes to different commands
never touch the same file. A file _intro.md next to them introduces the whole category. The pages of the commands are
named like the commands (docs/wiki/CreateTexture.md) because the GitHub wiki has one flat list of pages. A command file
holds:

  Free text, including ```blitzbasic examples (compiled by check) and ![images](media/blitz3d/x.png).
  @param width  Width in pixels, rounded up to a power of two.
  @returns      A texture handle.
  @gap          What differs from the original or is not implemented.

Differences.md is never edited by hand. It is a list of links, made by build from two places:

  * Every command with a @gap line is listed with a link to the "Differences and known gaps" part of its page.
  * Every page in tools/wiki/pages/ with a line "@difference One sentence summary." is listed as a feature, so a
    difference that no single command causes (mip maps, the depth buffer, new types) gets a file of its own there.
"""
import argparse
import collections
import os
import re
import subprocess
import sys
import tempfile

HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, HERE)
sys.path.insert(0, os.path.join(HERE, ".."))
import categories  # noqa: E402
import suite_functions  # noqa: E402

ROOT = os.path.normpath(os.path.join(HERE, "..", ".."))
LIST = os.path.join(ROOT, "tests", "suite", "functions.txt")
WIKI = os.path.join(ROOT, "docs", "wiki")
TEXT = os.path.join(HERE, "text")
PAGES = os.path.join(HERE, "pages")
# The header that the repository puts on its files, which the generated pages get once, from write().
COPYRIGHT = re.compile(r"<!-- AUTOGENERATED COPYRIGHT HEADER START -->.*?<!-- AUTOGENERATED COPYRIGHT HEADER END -->\n?", re.S)

HEADER = ("<!-- AUTOGENERATED COPYRIGHT HEADER START -->\n"
          "<!-- Copyright (C) 2026 Claude <noreply@anthropic.com> -->\n"
          "<!-- AUTOGENERATED COPYRIGHT HEADER END -->\n")
NOTE = "<!-- Generated by tools/wiki/wiki.py. Edit tools/wiki/text/ instead of this file. -->\n"
# The long names of the compiler (blitz::types::display), so the pages show `Int32` and not `%`.
TYPES = {"%": "Int32", "#": "Float32", "$": "String", "&": "UInt64", "": "Int32"}
DIALECT_ORDER = [categories.BASIC, categories.B3D, categories.PLUS]
DIALECT_TEXT = {
    categories.BASIC: "Commands that exist in BlitzBasic, Blitz3D and BlitzPlus alike.",
    categories.B3D: "Commands for the 3D world. They need a 3D graphics mode (`Graphics3D`).",
    categories.PLUS: "Commands that only BlitzPlus has: windows, gadgets, events and system access.",
}


INTROS = {}
# The sections of a command page, in order. Only the first, second and last are always there.
PAGE_SECTIONS = ["Command Syntax", "Description", "Parameters", "Examples", "Media", "Related Commands"]
# Appended to every list entry and title of a command that the original Blitz products do not have. Which commands
# those are comes from EXTENSIONS in tools/suite_functions.py, the list of what BlitzLLVM adds.
EXTENSION_MARK = "\u3014BlitzLLVM\u3015"
# The icon of each product, in media/icons. The help of the originals names the products a command works in.
ICONS = {"Blitz2D": ("BlitzBasic", "help_bb"), "BlitzPlus": ("BlitzPlus", "help_bp"), "Blitz3D": ("Blitz3D", "help_b3d"),
         "BlitzLLVM": ("BlitzLLVM", "help_llvm")}


class Command:
    def __init__(self, key, module, signature):
        self.key, self.module = key, module
        m = re.match(r"^([%#$&]?)(\w+)(.*)$", signature)
        self.ret = TYPES[m.group(1)] if m.group(1) else "None"
        self.name = m.group(2)
        self.params = [(TYPES[s], n, d) for s, n, d in re.findall(r"([%#$])(\w+)(?:=([^%#$]*))?", m.group(3))]
        self.dialect, self.category = categories.categorize(key, module)
        self.text = ""
        self.doc = {}

    @property
    def page(self):
        return "%s-%s" % (self.dialect, self.category.replace(" ", "-"))

    @property
    def extension(self):
        return self.key in suite_functions.EXTENSIONS

    @property
    def mark(self):
        return " " + EXTENSION_MARK if self.extension else ""

    @property
    def link(self):
        return "[%s](%s)%s" % (self.name, self.name, self.mark)

    def signature(self):
        name = self.name if self.ret == "None" else "%s:%s" % (self.name, self.ret)
        if not self.params:
            return name
        parts = ["%s:%s%s" % (n, t, "=" + d if d else "") for t, n, d in self.params]
        return "%s %s" % (name, ", ".join(parts))


def load():
    commands = []
    with open(LIST, encoding="utf-8") as f:
        for line in f:
            if line.startswith("#") or not line.strip():
                continue
            key, module, state, sig = line.rstrip("\n").split("\t")
            commands.append(Command(key, module, sig))
    by_path = {(c.dialect, c.category.replace(" ", "-"), c.name): c for c in commands}
    if len(by_path) != len(commands):
        raise SystemExit("two commands share a dialect, category and name")
    # Hand written text.
    if os.path.isdir(TEXT):
        for dialect in sorted(os.listdir(TEXT)):
            for category in sorted(os.listdir(os.path.join(TEXT, dialect))):
                for fn in sorted(os.listdir(os.path.join(TEXT, dialect, category))):
                    path = os.path.join(TEXT, dialect, category, fn)
                    name = os.path.splitext(fn)[0]
                    with open(path, encoding="utf-8") as f:
                        body = COPYRIGHT.sub("", f.read()).strip()
                    if name == "_intro":
                        INTROS["%s-%s" % (dialect, category)] = body
                        continue
                    c = by_path.get((dialect, category, name))
                    if c is None:
                        raise SystemExit("%s: '%s' is not a command of %s > %s" % (path, name, dialect,
                                                                                  category.replace("-", " ")))
                    c.text = body
    return commands


def split_text(text):
    """Separates the @param/@returns/@gap lines from the free text."""
    free, doc = [], {"param": {}, "returns": "", "gap": []}
    for line in text.split("\n"):
        m = re.match(r"^@(param|returns|gap)\s*(\w+)?\s*(.*)$", line)
        if not m:
            free.append(line)
        elif m.group(1) == "param":
            doc["param"][m.group(2)] = m.group(3).strip()
        elif m.group(1) == "returns":
            doc["returns"] = ((m.group(2) or "") + " " + m.group(3)).strip()
        else:
            doc["gap"].append(((m.group(2) or "") + " " + m.group(3)).strip())
    return "\n".join(free).strip(), doc


_WRITTEN = set()


def write(name, body):
    if name in _WRITTEN:
        raise SystemExit("two wiki pages are called %s" % name)
    _WRITTEN.add(name)
    with open(os.path.join(WIKI, name + ".md"), "w", encoding="utf-8", newline="\n") as f:
        f.write(HEADER + NOTE + body.rstrip("\n") + "\n")


_VERBS = {"get", "set", "create", "load", "free", "count", "add", "delete", "copy", "find", "read", "write", "open",
          "close", "clear", "update", "start", "stop", "is"}


def words(name):
    return re.findall(r"[A-Z]+(?![a-z])|[A-Z][a-z0-9]*|[a-z0-9]+|\d+", name)


def related(c, siblings, limit=8):
    """The commands of the same category that share words with this one, such as Get/Set pairs and common prefixes.
    Falls back to the neighbours in the alphabet, so that every page has some."""
    w = [x.lower() for x in words(c.name)]
    stem = w[1:] if w[0] in _VERBS and len(w) > 1 else w
    scored = []
    for o in siblings:
        if o is c:
            continue
        ow = [x.lower() for x in words(o.name)]
        ostem = ow[1:] if ow[0] in _VERBS and len(ow) > 1 else ow
        score = 0
        if ostem == stem:
            score += 10
        score += 2 * len(os.path.commonprefix([w, ow]))
        score += 2 * len(os.path.commonprefix([w[::-1], ow[::-1]]))
        score += len(set(stem) & set(ostem))
        if score:
            scored.append((-score, o.key, o))
    result = [o for _, _, o in sorted(scored)[:limit]]
    if len(result) < 4:
        ordered = sorted(siblings, key=lambda o: o.key)
        i = ordered.index(c)
        for o in ordered[max(0, i - 2):i] + ordered[i + 1:i + 3]:
            if o not in result and len(result) < 4:
                result.append(o)
    return sorted(result, key=lambda o: o.key)


def nav(c):
    """The links at the top and bottom of a command page, centered. The blank lines let the wiki render the Markdown
    inside the div."""
    return ('<div align="center">\n\n[Command Index](Command-Index) · [%s](%s) · [%s](%s)\n\n</div>\n' %
            (c.dialect, c.dialect, c.category, c.page))


def command_page(c, siblings):
    free, doc = split_text(re.sub(r"^;(media .*|run)\n", "", c.text, flags=re.M))
    # Prose before the first code block is the description, the code blocks (with the prose between them) are the
    # examples, and the images are the media, wherever the text file has them.
    media = re.findall(r"^!\[[^\]]*\]\([^)]+\)[ \t]*$", free, re.M)
    free = re.sub(r"^!\[[^\]]*\]\([^)]+\)[ \t]*\n?", "", free, flags=re.M).strip()
    m = re.search(r"^```", free, re.M)
    description, examples = (free[:m.start()], free[m.start():]) if m else (free, "")
    description, examples = description.strip(), examples.strip()
    import helpref
    ref = helpref.read(c.key)
    # The GitHub wiki strips style attributes, so the icons float to the right with align="right". The first image
    # floats furthest right, which is why they are written in reverse.
    names = ["BlitzLLVM"] if c.extension else (ref["dialects"] if ref else [])
    icons = "".join('<img align="right" src="media/icons/%s.svg" alt="%s" title="%s" width="80">' %
                    (ICONS[n][1], ICONS[n][0], ICONS[n][0]) for n in reversed(names))
    out = [icons + "\n" if icons else "", "# %s%s\n" % (c.name, c.mark),
           nav(c) + "\n",
           "## Command Syntax\n", "```blitzbasic\n%s\n```\n" % c.signature(), "## Description\n"]
    if c.extension:
        out.append("**%s** This command does not exist in the original Blitz products. BlitzLLVM adds it.\n" %
                   EXTENSION_MARK)
    out.append(description + "\n" if description else "_Not documented yet._\n")
    if doc["gap"]:
        out.append("**Differences and known gaps:**\n")
        out.extend("* " + g for g in doc["gap"])
        out.append("")
    if c.params or doc["returns"]:
        out.append("## Parameters\n")
    if c.params:
        out.append("| Parameter | Type | Default | Description |\n|---|---|---|---|")
        for t, n, d in c.params:
            out.append("| `%s` | %s | %s | %s |" % (n, t, "`%s`" % d if d else "required", doc["param"].get(n, "")))
        out.append("")
    if doc["returns"]:
        out.append("**Returns:** %s\n" % doc["returns"])
    if examples:
        out.append("## Examples\n")
        out.append(examples + "\n")
    if media:
        out.append("## Media\n")
        out.extend(x.strip() + "\n" for x in media)
    out.append("## Related Commands\n")
    out.extend("* " + o.link for o in related(c, siblings))
    out.append("")
    out.append(nav(c))
    return "\n".join(out)


def category_page(dialect, category, cmds):
    out = ["# %s: %s\n" % (dialect, category), categories.CATEGORY_TEXT.get((dialect, category), "") + "\n",
           INTROS[cmds[0].page] + "\n" if cmds[0].page in INTROS else "",
           "Back to [%s](%s) or the [Command Index](Command-Index).\n" % (dialect, dialect)]
    out.extend("* " + c.link for c in sorted(cmds, key=lambda c: c.key))
    return "\n".join(out)


GENERIC_FIRST = ["Installation", "Building", "Language", "Warnings", "Differences", "Releasing"]


def generic_pages(cats):
    """Every page that is not a command, category or dialect page, as (name, title). Found by listing the wiki folder,
    so a new hand written or generated page shows up in the sidebar without anyone editing a list."""
    own = {"Home", "Command-Index", "_Sidebar"} | set(DIALECT_ORDER)
    own.update(page for page, _, _ in feature_pages())  # these are listed on the Differences page
    for dialect in cats:
        for category, cmds in cats[dialect].items():
            own.add(cmds[0].page)
            own.update(c.name for c in cmds)
    result = []
    for fn in os.listdir(WIKI):
        if not fn.endswith(".md") or fn[:-3] in own:
            continue
        with open(os.path.join(WIKI, fn), encoding="utf-8") as f:
            m = re.search(r"^# (.+)$", f.read(), re.M)
        result.append((fn[:-3], m.group(1).strip() if m else fn[:-3].replace("-", " ")))
    first = {n: i for i, n in enumerate(GENERIC_FIRST)}
    return sorted(result, key=lambda p: (first.get(p[0], len(first)), p[1].lower()))


def sidebar(cats):
    """The GitHub wiki shows _Sidebar.md next to every page. Dialects and categories fold open with <details>, so the
    sidebar stays short until a submenu is opened. A dialect is a <details> with a bold title. Below it, each
    category is a <details> inside the <li> of a list, and holds the <ul> of its commands, so that a submenu is
    indented under its parent. There are no headings, because their anchors get in the way of the page navigation.
    The menu is HTML because Markdown does not render inside <details>, and it uses no styling because the wiki strips
    it."""
    out = ['<a href="Home">Home</a> · <a href="Command-Index">Command Index</a>', "", "<hr>", ""]
    generic = generic_pages(cats)
    if generic:
        out.append("<ul>")
        out.extend('<li><a href="%s">%s</a></li>' % p for p in generic)
        out.append("</ul>")
        out += ["", "<hr>", ""]
    for dialect in DIALECT_ORDER:
        out.append('<details><summary><b><a href="%s">%s</a></b></summary>' % (dialect, dialect))
        out.append("<ul>")
        for category in sorted(cats[dialect]):
            cmds = sorted(cats[dialect][category], key=lambda c: c.key)
            out.append('<li><details><summary><a href="%s">%s</a> (%d)</summary>' %
                       (cmds[0].page, category, len(cmds)))
            out.append("<ul>")
            out.extend('<li><a href="%s">%s</a>%s</li>' % (c.name, c.name, c.mark) for c in cmds)
            out.append("</ul>")
            out.append("</details></li>")
        out.append("</ul>")
        out.append("</details>")
        out.append("")
    return "\n".join(out)


DIFFERENCE = re.compile(r"^@difference[ \t]*(.*)\n?", re.M)
DIFFERENCES_TEXT = (
    "# Differences from the originals\n\n"
    "Where BlitzLLVM can not behave like Blitz3D or BlitzPlus, because the system they were made for is gone, or where it "
    "does more than they did, this is how it behaves instead.\n\n"
    "This page is made from the pages it links to (see `tools/wiki/wiki.py`), so it is not edited by hand: "
    "a command lists its differences with `@gap` in its text file, and a difference that no single command causes "
    "gets a page in `tools/wiki/pages/` with a line `@difference` and a one sentence summary.\n")


def feature_pages():
    """The pages in tools/wiki/pages/ that have an @difference line, as (page, title, summary)."""
    result = []
    for fn in sorted(os.listdir(PAGES)):
        with open(os.path.join(PAGES, fn), encoding="utf-8") as f:
            body = f.read()
        m = DIFFERENCE.search(body)
        if m:
            title = re.search(r"^# (.+)$", body, re.M)
            result.append((fn[:-3], title.group(1) if title else fn[:-3], m.group(1).strip()))
    return result


def first_sentence(text):
    m = re.match(r"(.+?[.!?])(?:\s|$)", text)
    return m.group(1) if m else text


def differences_page(commands):
    out = [DIFFERENCES_TEXT, "## Features\n", "Differences that are not caused by one command.\n"]
    out.extend("* [%s](%s): %s" % (title, page, summary) for page, title, summary in
               sorted(feature_pages(), key=lambda f: f[1].lower()))
    out += ["", "## Commands\n", "Commands that differ from the original or are not finished, with the first of the "
            "differences from the \"Differences and known gaps\" part of their page.\n"]
    gapped = sorted((c for c in commands if split_text(c.text)[1]["gap"]), key=lambda c: c.name.lower())
    out.extend("* [%s](%s#differences-and-known-gaps)%s: %s" % (c.name, c.name, c.mark,
                                                              first_sentence(split_text(c.text)[1]["gap"][0]))
               for c in gapped)
    return "\n".join(out)


def build(commands):
    cats = collections.defaultdict(lambda: collections.defaultdict(list))
    for c in commands:
        cats[c.dialect][c.category].append(c)
    # Pages of commands that were removed or renamed must not stay behind. Hand written pages lack the note.
    for fn in os.listdir(WIKI):
        if fn.endswith(".md"):
            with open(os.path.join(WIKI, fn), encoding="utf-8") as f:
                if NOTE in f.read(1000):
                    os.remove(os.path.join(WIKI, fn))
    for dialect in DIALECT_ORDER:
        for category, cmds in cats[dialect].items():
            write(cmds[0].page, category_page(dialect, category, cmds))
            for c in cmds:
                write(c.name, command_page(c, cmds))
        out = ["# %s\n" % dialect, DIALECT_TEXT[dialect] + "\n", "Back to [Home](Home) or the [Command Index](Command-Index).\n"]
        for category in sorted(cats[dialect]):
            cmds = cats[dialect][category]
            out.append("* [%s](%s) (%d): %s" % (category, cmds[0].page, len(cmds),
                                                 categories.CATEGORY_TEXT.get((dialect, category), "")))
        write(dialect, "\n".join(out))
    for fn in sorted(os.listdir(PAGES)):
        with open(os.path.join(PAGES, fn), encoding="utf-8") as f:
            body = re.sub(r"^;(media .*|run)\n", "", COPYRIGHT.sub("", f.read()), flags=re.M)
        write(fn[:-3], DIFFERENCE.sub("", body))
    write("Differences", differences_page(commands))
    out = ["# Command Index\n", "Every command from A to Z. See [Home](Home) to browse by dialect and category.\n"]
    letters = collections.defaultdict(list)
    for c in sorted(commands, key=lambda c: c.key):
        letters[c.name[0].upper()].append(c)
    out.append(" ".join("[%s](#%s)" % (l, l.lower()) for l in sorted(letters)) + "\n")
    for l in sorted(letters):
        out.append("## %s\n" % l)
        out.extend("* " + c.link for c in letters[l])
        out.append("")
    write("Command-Index", "\n".join(out))
    write("_Sidebar", sidebar(cats))


def check(commands, blitzcc):
    errors = []
    for c in commands:
        if c.category == "Other":
            errors.append("%s has no category" % c.name)
    pages = {fn[:-3] for fn in os.listdir(WIKI) if fn.endswith(".md")}
    for fn in sorted(os.listdir(WIKI)):
        if not fn.endswith(".md"):
            continue
        with open(os.path.join(WIKI, fn), encoding="utf-8") as f:
            body = f.read()
        for m in re.finditer(r"\[\[([^\]|\\]+)", body):
            if m.group(1) not in pages:
                errors.append("%s links to the missing page %s" % (fn, m.group(1)))
        for m in re.finditer(r"\]\(([A-Za-z0-9_-]+)(?:#[^)\s]*)?\)", body):
            if m.group(1) not in pages:
                errors.append("%s links to the missing page %s" % (fn, m.group(1)))
        for m in re.finditer(r"\]\((media/[^)\s]+)\)", body):
            if not os.path.exists(os.path.join(WIKI, m.group(1))):
                errors.append("%s uses the missing file %s" % (fn, m.group(1)))
    for c in commands:
        path = os.path.join(WIKI, c.name + ".md")
        if os.path.exists(path):
            with open(path, encoding="utf-8") as f:
                heads = [h for h in re.findall(r"^## (.+)$", f.read(), re.M)]
            order = [h for h in heads if h in PAGE_SECTIONS]
            if order != sorted(set(order), key=PAGE_SECTIONS.index) or len(order) != len(set(order)):
                errors.append("%s has the sections %s, they must be in the order %s" %
                              (c.name, ", ".join(order), ", ".join(PAGE_SECTIONS)))
            for need in ("Command Syntax", "Description", "Related Commands"):
                if need not in heads:
                    errors.append("%s has no '%s' section" % (c.name, need))
    for page, title, summary in feature_pages():
        if not summary:
            errors.append("%s has an @difference line without a summary" % page)
    for fn in sorted(os.listdir(PAGES)):
        with open(os.path.join(PAGES, fn), encoding="utf-8") as f:
            if "@difference" in f.read() and fn[:-3] not in pages:
                errors.append("%s is not built, run wiki.py build" % fn)
    if "Differences" not in pages:
        errors.append("Differences is missing, run wiki.py build")
    for root, _, files in os.walk(TEXT):
        for fn in files:
            with open(os.path.join(root, fn), encoding="utf-8") as f:
                if re.search(r"\]\(Differences#|\[\[Differences#", f.read()):
                    errors.append("%s links into Differences, which has no sections: link the feature page" % fn)
    if blitzcc:
        texts = [(c.name, c.text) for c in commands]
        for fn in sorted(os.listdir(PAGES)):
            with open(os.path.join(PAGES, fn), encoding="utf-8") as f:
                texts.append((fn, f.read()))
        for name, text in texts:
            for i, m in enumerate(re.finditer(r"```blitzbasic\n(.*?)```(?:\n+```text\n(.*?)```)?", text, re.S)):
                src, expect = m.group(1), m.group(2)
                if src.lstrip().startswith(";nocompile"):
                    continue
                run = src.startswith(";run\n")
                with tempfile.TemporaryDirectory() as d:
                    path = os.path.join(d, "example.bb")
                    with open(path, "w", encoding="utf-8") as f:
                        f.write(src)
                    exe = os.path.join(d, "example")
                    r = subprocess.run([blitzcc, "+q", "-o", exe, path], capture_output=True, text=True)
                    if r.returncode != 0:
                        errors.append("%s example %d does not compile:\n%s" % (name, i + 1, r.stdout + r.stderr))
                    elif run:
                        r = subprocess.run([exe], capture_output=True, text=True, cwd=d, timeout=60,
                                           env=dict(os.environ, BLITZ_HEADLESS="1"))
                        if expect is None or r.stdout.split() != expect.split():
                            errors.append("%s example %d printed:\n%s\nbut the page says:\n%s" %
                                          (name, i + 1, r.stdout, expect))
    for e in errors:
        print(e, file=sys.stderr)
    return 1 if errors else 0


def main():
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("action", choices=["build", "check"])
    ap.add_argument("--blitzcc")
    args = ap.parse_args()
    commands = load()
    if args.action == "build":
        build(commands)
        return 0
    return check(commands, args.blitzcc)


if __name__ == "__main__":
    sys.exit(main())
